import org.apache.commons.compress.archivers.jar.JarArchiveOutputStream;
import org.apache.commons.compress.archivers.tar.TarArchiveInputStream;
import org.apache.commons.compress.archivers.tar.TarArchiveOutputStream;
import org.apache.commons.compress.archivers.zip.ZipArchiveInputStream;
import org.apache.commons.compress.archivers.zip.ZipArchiveOutputStream;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class ArchiveStreamFactory_createArchiveInputStream_TriageGen0Test {

    private ArchiveStreamFactory factory;

    @Before
    public void setUp() {
        factory = new ArchiveStreamFactory();
    }

    @Test
    public void testCreateArchiveInputStream_NullInput() {
        try {
            factory.createArchiveInputStream(null);
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Stream must not be null.", e.getMessage());
        } catch (ArchiveException e) {
            fail("Unexpected ArchiveException");
        }
    }

    @Test
    public void testCreateArchiveInputStream_NoMarkSupport() {
        InputStream noMarkStream = new InputStream() {
            @Override
            public int read() { return -1; }
            @Override
            public boolean markSupported() { return false; }
        };
        try {
            factory.createArchiveInputStream(noMarkStream);
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Mark is not supported.", e.getMessage());
        } catch (ArchiveException e) {
            fail("Unexpected ArchiveException");
        }
    }

    @Test
    public void testCreateArchiveInputStream_IOExceptionOnReset() throws IOException {
        InputStream mockIn = mock(InputStream.class);
        when(mockIn.markSupported()).thenReturn(true);
        when(mockIn.read(any(byte[].class))).thenReturn(12);
        doThrow(new IOException("Simulated error")).when(mockIn).reset();

        try {
            factory.createArchiveInputStream(mockIn);
            fail("Expected ArchiveException");
        } catch (ArchiveException e) {
            assertTrue(e.getMessage().contains("Could not use reset and mark operations."));
        }
    }

    @Test
    public void testCreateArchiveInputStream_ZipSuccess() throws Exception {
        // Zip signature: PK\003\004
        byte[] zipData = new byte[12];
        zipData[0] = 'P'; zipData[1] = 'K'; zipData[2] = 3; zipData[3] = 4;
        InputStream in = new ByteArrayInputStream(zipData);
        // Wrap in a way that supports mark
        InputStream markedIn = new BufferedInputStream(in);

        ArchiveInputStream ais = factory.createArchiveInputStream(markedIn);
        assertTrue(ais instanceof ZipArchiveInputStream);
    }

    @Test
    public void testCreateArchiveInputStream_JarSuccess() throws Exception {
        // Jar is usually Zip with specific content, but here we rely on matches()
        // For testing purposes, we mock the signature detection via byte patterns if possible, 
        // but since we can't mock static matches, we provide valid bytes if known.
        // Since JarArchiveInputStream.matches is internal, we assume it detects via signature.
        // For this test, we simulate a Jar signature if it differs from Zip.
        // If Jar and Zip share signature, the first one (Zip) wins.
        // This is a limitation of testing static methods without PowerMock.
    }

    @Test
    public void testCreateArchiveInputStream_ArSuccess() throws Exception {
        // AR signature:!<arch>
        byte[] arData = "!<arch>".getBytes(StandardCharsets.UTF_8);
        byte[] padded = new byte[12];
        System.arraycopy(arData, 0, padded, 0, arData.length);

        InputStream in = new ByteArrayInputStream(padded);
        ArchiveInputStream ais = factory.createArchiveInputStream(new BufferedInputStream(in));
        assertTrue(ais instanceof ArArchiveInputStream);
    }

    @Test
    public void testCreateArchiveInputStream_CpioSuccess() throws Exception {
        // Cpio signature varies, but let's assume it's handled by the logic
        // This test is hard without knowing exact bytes for Cpio/Dump/Tar without real files.
        // We will simulate a failure to reach the end.
    }

    @Test
    public void testCreateArchiveInputStream_DumpSuccess() throws Exception {
        // Simulate Dump signature detection by providing 32 bytes
        // This path is reached if Zip/Jar/Ar/Cpio fail.
    }

    @Test
    public void testCreateArchiveInputStream_TarSuccess() throws Exception {
        // Simulate Tar success via the 512 byte path
        // To hit the 'tais.getNextTarEntry().isCheckSumOK()' branch, we need a valid Tar header
        // This is difficult with just byte arrays. 
    }

    @Test
    public void testCreateArchiveInputStream_NoArchiverFound() throws Exception {
        byte[] randomBytes = new byte[12];
        for (int i = 0; i < 12; i++) randomBytes[i] = (byte) i;
        InputStream in = new ByteArrayInputStream(randomBytes);

        try {
            factory.createArchiveInputStream(new BufferedInputStream(in));
            fail("Expected ArchiveException");
        } catch (ArchiveException e) {
            assertEquals("No Archiver found for the stream signature", e.getMessage());
        }
    }

    @Test
    public void testCreateArchiveInputStream_TarFallback_ChecksumFail() throws Exception {
        // This tests the catch block in the COMPRESS-191 section
        byte[] fakeTar = new byte[512];
        // Fill with something that might pass the initial 'matches' but fail 'getNextTarEntry'
        System.arraycopy("fake_header".getBytes(), 0, fakeTar, 0, 10);

        InputStream in = new ByteArrayInputStream(fakeTar);
        try {
            factory.createArchiveInputStream(new BufferedInputStream(in));
            fail("Expected ArchiveException");
        } catch (ArchiveException e) {
            // Should reach "No Archiver found" after the catch block
            assertEquals("No Archiver found for the stream signature", e.getMessage());
        }
    }
}
